"Урок 18. Природные явления. Вода": "Dars 18. Tabiat hodisalari. Suv",
"Природные явления. Вода": "Tabiat hodisalari. Suv",
"Различать подгруппы струнных инструментов и называть произведения о воде и грозе.": "Torli asboblarning kichik guruhlarini ajrata olish va suv hamda momaqaldiroq haqidagi asarlarni nomlash.",
"Струнные инструменты": "Torli cholg‘u asboblari",
"Это самая многочисленная группа инструментов. Их называют основой симфонического оркестра.": "Bu asboblarning eng ko‘p sonli guruhi. Ular simfonik orkestrning asosi deb ataladi.",
"Народные струнные": "Xalq torli asboblari",
"Семейство народных струнных инструментов тоже очень разнообразно. Все струнные инструменты в мире условно делят на три подгруппы.": "Xalq torli asboblari oilasi ham juda xilma-xil. Dunyodagi barcha torli asboblar shartli ravishda uchta kichik guruhga bo‘linadi.",
"Щипковые": "Tirnaladigan (torli) cholg‘ular",
"Звук получают, защипывая струну пальцами или специальной пластинкой — плектром. Это домбра, гитара, арфа.": "Tovush torni barmoqlar yoki maxsus plastinka — plektr bilan chertib hosil qilinadi. Bular dombra, gitara, arfa.",
"Смычковые и ударные": "Kamonli va zarbli",
"У смычковых звук извлекают смычком из конского волоса: виолончель, кобыз. У ударных по струнам бьют палочками или молоточками: фортепиано, цимбалы.": "Kamonli asboblarda tovush ot yolidan qilingan kamon bilan chiqariladi: violonchel, kobyz. Zarbli asboblarda torlarga cho‘p yoki bolg‘achalar bilan uriladi: fortepiano, simbal.",
"Эолова арфа": "Eol arfasi",
"Её струны звучат от колебания воздуха, и музыкант ей не нужен. Это деревянный ящик с отверстием, внутри которого натянуты струны.": "Uning torlari havoning tebranishidan ovoz chiqaradi, musiqachi kerak emas. Bu teshigi bor yog‘och quti bo‘lib, ichiga torlar tortilgan.",
"Разложи струнные инструменты по подгруппам": "Torli asboblarni kichik guruhlarga ajrat",
"Определи, к какой подгруппе относится инструмент или способ звукоизвлечения.": "Asbob yoki tovush chiqarish usuli qaysi kichik guruhga tegishli ekanini aniqla.",
"В какую подгруппу относится?": "Qaysi kichik guruhga kiradi?",
"Смычковые": "Kamonli",
"Ударные": "Urma cholg‘ular",
"Домбра": "Dombra",
"Струны защипывают пальцами.": "Torlarni barmoqlar bilan chertadilar.",
"Гитара": "Gitara",
"Звук получают защипыванием струн.": "Tovush torlarni chertib hosil qilinadi.",
"Арфа": "Arfa",
"Виолончель": "Violonchel",
"Звучит с помощью смычка.": "Kamon yordamida chalinadi.",
"Кобыз": "Qobiz",
"Это народный инструмент со смычком.": "Bu kamonli xalq asbobi.",
"Смычок из конского волоса": "Ot yolidan qilingan kamon",
"Им водят по струнам.": "Uni torlar bo‘ylab yurgizadilar.",
"Фортепиано": "Fortepiano",
"Звук получается от удара молоточков по струнам.": "Tovush bolg‘achalarning torlarga urilishidan hosil bo‘ladi.",
