"Духовые инструменты": "Puflama cholg‘u asboblari",
"Это инструменты, которые звучат благодаря воздуху, который вдувает музыкант. Они делятся на три группы: медные, деревянные и клавишные.": "Bu musiqachi puflagan havo tufayli ovoz chiqaradigan asboblar. Ular uch guruhga bo‘linadi: mis, yog‘och va klavishli.",
"Медные и деревянные": "Mis va yog‘och",
"К медным относятся труба, валторна, туба, горн, фанфары. К деревянным — дудка, флейта, саксофон, кларнет, фагот, балабан и зурна.": "Mis puflama asboblarga truba, valtorna, tuba, shox, fanfara kiradi. Yog‘och puflama asboblarga — dudka, nay (fleyta), saksofon, klarnet, fagot, balaban va surnay kiradi.",
"Клавишные духовые": "Klavishli puflama asboblar",
"К клавишным духовым относятся фисгармония, аккордеон, мелодика, баян и орган.": "Klavishli puflama asboblarga fisgarmoniya, akkordeon, melodika, bayan va organ kiradi.",
"Сценические эффекты": "Sahna effektlari",
"Так называют звуковое и световое сопровождение, иллюзии движения и превращения в спектакле, концерте или шоу. Слово пришло из латыни и означает «исполнение».": "Spektakl, konsert yoki shouda tovush va yorug‘lik bilan bezash, harakat va o‘zgarish illyuziyalari shunday ataladi. So‘z lotin tilidan kelgan va «ijro» degan ma’noni anglatadi.",
"Рихард Вагнер": "Rixard Vagner",
"Немецкий композитор и дирижёр (1813–1883). Его музыка «Полёт валькирий» рисует приближение крылатых коней. Помогают в этом динамические оттенки.": "Nemis bastakori va dirijyori (1813–1883). Uning «Valkiriyalar parvozi» musiqasi qanotli otlarning yaqinlashishini tasvirlaydi. Bunda dinamik ohanglar yordam beradi.",
"Разложи духовые инструменты по группам": "Puflama asboblarni guruhlarga ajrat",
