"Различать, как музыка передаёт дикий и укрощённый огонь, и называть произведения С. Прокофьева и П.И. Чайковского.": "Musiqa yovvoyi va bo‘ysundirilgan olovni qanday ifodalashini ajrata olish hamda S. Prokofyev va P.I. Chaykovskiy asarlarini nomlash.",
"Огненный смерч": "Olovli quyun",
"Это очень яркое, но очень опасное природное явление. Чаще всего оно возникает в горящем лесу, а ветер там сильнее 160 километров в час.": "Bu juda yorqin, lekin juda xavfli tabiat hodisasi. U ko‘pincha yonayotgan o‘rmonda paydo bo‘ladi, u yerda shamol soatiga 160 kilometrdan kuchliroq bo‘ladi.",
"Прокофьев и «Каменный цветок»": "Prokofyev va «Tosh gul»",
"Композитор С. Прокофьев в балете «Каменный цветок» изобразил музыкой похожее явление. Танец Огневушки-поскакушки передаёт неуправляемый характер огненного вихря.": "Bastakor S. Prokofyev «Tosh gul» baletida shunga o‘xshash hodisani musiqa bilan tasvirlagan. Ognevushka-poskakushka raqsi olovli girdobning nazoratsiz xarakterini ifodalaydi.",
"Укрощённый огонь": "Bo‘ysundirilgan olov",
"Человек научился управлять огнём: он обогревает и освещает жильё. Такой огонь спокойный и доброжелательный.": "Inson olovni boshqarishni o‘rgandi: u uyni isitadi va yoritadi. Bunday olov sokin va mehribon.",
"Чайковский и «У камелька»": "Chaykovskiy va «Kamin yonida»",
"Пьеса «У камелька» входит в цикл «Времена года» П.И. Чайковского. В ней музыка передаёт спокойный, добрый огонь и чувство тепла.": "«Kamin yonida» pyesasi P.I. Chaykovskiyning «Yil fasllari» turkumiga kiradi. Unda musiqa sokin, mehribon olovni va iliqlik tuyg‘usini ifodalaydi.",
"Огонь и безопасность": "Olov va xavfsizlik",
"Огонь может стать причиной пожара, поэтому очень важно соблюдать правила пожарной безопасности. Спички — не игрушка, а огонь — не забава!": "Olov yong‘inga sabab bo‘lishi mumkin, shuning uchun yong‘in xavfsizligi qoidalariga rioya qilish juda muhim. Gugurt — o‘yinchoq emas, olov — o‘yin emas!",
