"Объяснять, что такое программная музыка, и называть примеры музыки, изображающей природу.": "Dasturli musiqa nima ekanini tushuntirish va tabiatni tasvirlaydigan musiqa misollarini aytish.",
"Музыкальная живопись": "Musiqiy rassomlik",
"Люди всегда делились впечатлениями от увиденного и услышанного. Есть даже выражение «музыкальная живопись» — музыка, которая рисует картины природы.": "Odamlar doim ko‘rgan va eshitganlaridan olgan taassurotlari bilan o‘rtoqlashgan. Hatto «musiqiy rassomlik» degan ibora ham bor — bu tabiat manzaralarini chizadigan musiqa.",
"Цикл П. Чайковского «Времена года» состоит из 12 пьес. Каждая пьеса — образ одного месяца года, чаще всего через пейзаж.": "P. Chaykovskiyning «Yil fasllari» turkumi 12 pyesadan iborat. Har bir pyesa yilning bir oyining obrazi bo‘lib, ko‘pincha manzara orqali ifodalanadi.",
"Настроение сезона": "Fasl kayfiyati",
"В небольших пьесах-акварелях отражено настроение сезона: зимние грёзы, весенняя свежесть, летнее раздолье, осенняя грусть.": "Kichik akvarel-pyesalarda fasl kayfiyati aks etgan: qishki hayollar, bahorgi tetiklik, yozgi kenglik, kuzgi g‘amginlik.",
"Программная музыка": "Dasturli musiqa",
"Это академическая музыка без слов, то есть инструментальная. Но к ней есть словесное указание на содержание: название или пояснение.": "Bu so‘zsiz akademik musiqa, ya’ni cholg‘u musiqasi. Lekin unga mazmuni haqida so‘z bilan ko‘rsatma beriladi: nom yoki izoh.",
"Заголовок и эпиграф": "Sarlavha va epigraf",
"Перед каждой из 12 миниатюр Чайковского есть заголовок и эпиграф — строчки из стихов русских поэтов. Они раскрывают характер музыки. Один из таких эпиграфов взят у А. Майкова.": "Chaykovskiyning har bir 12 ta miniatyurasi oldida sarlavha va epigraf bor — rus shoirlarining she’riy misralari. Ular musiqaning xarakterini ochib beradi. Epigraflardan biri A. Maykovdan olingan.",
"Кто или что это?": "Bu kim yoki nima?",
"Разложи карточки: произведение, термин или автор.": "Kartochkalarni joylashtir: asar, atama yoki muallif.",
"К какой группе относится?": "Qaysi guruhga kiradi?",
