"Урок 22. Музыка-призыв": "Dars 22. Chorlovchi musiqa",
"Музыка-призыв": "Chorlovchi musiqa",
"Объяснять, как музыка призывает беречь природу, и называть песни и их авторов.": "Musiqa tabiatni asrashga qanday chaqirishini tushuntirish, qo‘shiqlar va ularning mualliflarini aytish.",
"Что такое призыв": "Chorlov nima",
"Призыв — это обращение, которое зовёт к действию. По-казахски это «шакыру», по-английски — «call».": "Chorlov — harakatga chaqiradigan murojaat. Qozoqchada bu «shaqyru», inglizchada — «call».",
"Музыка, которая зовёт": "Chaqiradigan musiqa",
"Многие музыкальные произведения не просто украшают нашу жизнь. Они становятся руководством к действию и помогают человеку сделать правильный выбор.": "Ko‘p musiqiy asarlar hayotimizni shunchaki bezamaydi. Ular harakatga qo‘llanma bo‘ladi va odamga to‘g‘ri tanlov qilishga yordam beradi.",
"Экологическая тема": "Ekologik mavzu",
"В музыке бывает экологическая тема — это охрана окружающей среды. Песни напоминают нам, что природу нужно беречь.": "Musiqada ekologik mavzu ham bo‘ladi — bu atrof-muhitni muhofaza qilish. Qo‘shiqlar bizga tabiatni asrash kerakligini eslatadi.",
"«Песня о земной красоте»": "«Yerdagi go‘zallik haqida qo‘shiq»",
"Эту песню написал Я. Дубравин. Она о красоте природы и о доброте, которой нужно делиться.": "Bu qo‘shiqni Ya. Dubravin yozgan. U tabiat go‘zalligi va ulashish kerak bo‘lgan mehribonlik haqida.",
"«Не дразните собак»": "«Itlarga tegmang»",
"Эта песня из кинофильма «Происшествие». Музыку написал Е. Птичкин, слова — М. Пляцковский. Песня призывает добро относиться к животным и красоте земли.": "Bu qo‘shiq «Voqea» kinofilmidan. Musiqasini E. Ptichkin, so‘zlarini M. Plyatskovskiy yozgan. Qo‘shiq hayvonlarga mehribon bo‘lishga va yer go‘zalligiga chaqiradi.",
"Береги природу": "Tabiatni asra",
"Барсик спрашивает: что помогает природе и животным, а что им вредит? Разложи карточки.": "Barsik so‘raydi: tabiat va hayvonlarga nima yordam beradi, nima zarar yetkazadi? Kartochkalarni joylashtir.",
"Так поступает друг природы": "Tabiat do‘sti shunday qiladi",
"Так поступать нельзя": "Bunday qilish mumkin emas",
"Посадить дерево": "Daraxt ekish",
"Пословица говорит: кто не сажал дерева, тому не лежать в тени.": "Maqolda aytiladi: daraxt ekmagan odam soyada yota olmaydi.",
