"Мой любимец": "Mening sevimlim",
"Объяснять, что такое нотное переложение, и называть музыкальные произведения о любимых животных.": "Notalarga qayta ishlanma nima ekanini tushuntirish va sevimli hayvonlar haqidagi musiqiy asarlarni aytish.",
"Конь в музыке": "Musiqadagi ot",
"У казахского народа самым любимым и почитаемым животным всегда был конь, скакун. Многие композиторы рисовали музыкой его стремительные, неудержимые скачки.": "Qozoq xalqi uchun eng sevimli va hurmatli hayvon doim ot, chopqir to‘riq bo‘lgan. Ko‘p kompozitorlar uning tez, to‘xtovsiz chopishini musiqada tasvirlagan.",
"Курмангазы и «Адай»": "Kurmangazy va «Adai»",
"Великий казахский композитор Курмангазы создал музыкальную картину «Адай». В ней не просто скачки: он показал мужественный, героический дух древнего казахского рода Адай.": "Buyuk qozoq kompozitori Kurmangazy «Adai» musiqiy manzarasini yaratgan. Unda shunchaki chopish emas: u qadimiy Adai qozoq urug‘ining mard, qahramonlik ruhini ko‘rsatgan.",
"Одно произведение — разное исполнение": "Bitta asar — turlicha ijro",
"Кюй «Адай» можно услышать в трёх исполнениях: на домбре, в оркестре и с электронными инструментами. Произведение одно, а исполнение разное.": "«Adai» kuyini uch xil ijroda eshitish mumkin: dombrada, orkestrda va elektron cholg‘ularda. Asar bitta, ijro esa turlicha.",
"Что такое переложение": "Qayta ishlanma nima",
"Переложение — это музыкальное произведение, изложенное в иной форме. Барсик говорит: мелодия та же, а звучит по-новому!": "Qayta ishlanma — boshqa shaklda bayon etilgan musiqiy asar. Barsik aytadi: kuy o‘sha, lekin yangicha jaranglaydi!",
"Песни о любимцах и о мире": "Sevimli hayvonlar va dunyo haqidagi qo‘shiqlar",
"У всех народов мира есть песни о домашних любимцах, например английская народная песня «Котятки и перчатки». А песня Л. Квинт «Здравствуй, мир» — о жеребёнке и о мире вокруг. Слово «мир» по-казахски — әлем.": "Dunyoning barcha xalqlarida uy sevimlilari haqida qo‘shiqlar bor, masalan, ingliz xalq qo‘shig‘i «Mushukchalar va qo‘lqoplar». L. Kvintning «Salom, dunyo» qo‘shig‘i esa toychoq va atrofdagi dunyo haqida. «Dunyo» so‘zi qozoqchada — alem.",
"Чья это песня или кюй?": "Bu kimning qo‘shig‘i yoki kuyi?",
