"Объяснять, как кюи Курмангазы и народные песни отражают любовь к Родине, и называть, что нужно беречь.": "Kurmangazy kuylari va xalq qo‘shiqlari Vatanga muhabbatni qanday aks ettirishini tushuntirish va nimani asrash kerakligini aytish.",
"Родина": "Vatan",
"Родина по-казахски — Отан, по-английски — Homeland. Это страна, где мы живём и которую любим.": "Vatan qozoqchada — Otan, inglizchada — Homeland. Bu biz yashaydigan va sevadigan yurt.",
"Любовь к Родине": "Vatanga muhabbat",
"В народе говорят, что любовь к Родине начинается у семейного очага, то есть в семье и дома.": "Xalq orasida aytishadi: Vatanga muhabbat oila o‘chog‘idan, ya’ni oiladan va uydan boshlanadi.",
"Красота родного края": "Ona yurtning go‘zalligi",
"В песнях, кюях, сказаниях и сказках авторы воспевали красоту родного края и призывали сохранять и оберегать её.": "Qo‘shiqlarda, kuylarda, rivoyatlarda va ertaklarda mualliflar ona yurtning go‘zalligini madh etgan va uni saqlashga, asrashga chaqirgan.",
"Кюй «Алатау»": "«Alatau» kuyi",
"Композитор Курмангазы Сагырбайулы изобразил в кюе величественные горные вершины и красивую природу Заилийского Алатау. Кюй можно услышать в исполнении на домбре и в оркестровом варианте.": "Bastakor Kurmangazy Sagyrbayuly kuyda Zayli Olatovining ulug‘vor tog‘ cho‘qqilarini va go‘zal tabiatini tasvirlagan. Kuyni dombrada ijroda ham, orkestr variantida ham eshitish mumkin.",
"Что мы бережём": "Biz nimani asraymiz",
"Люди стараются сохранить не только природные богатства, но и культурное наследие своего народа. Песня «Наурыз жыры» (музыка М. Жаманкуловой) — о празднике Наурыз.": "Odamlar nafaqat tabiat boyliklarini, balki o‘z xalqining madaniy merosini ham saqlashga harakat qiladi. «Nauryz zhyry» qo‘shig‘i (musiqasi M. Jamankulova) Navro‘z bayrami haqida.",
"Разложи по произведениям": "Asarlar bo‘yicha ajrat",
"Барсик просит разобраться, что относится к кюю, а что к песне.": "Barsik kuy nimaga, qo‘shiq nimaga tegishli ekanini aniqlashni so‘raydi.",
