"Урок 26. Как прекрасен этот мир": "Dars 26. Bu dunyo qanday go‘zal",
"Как прекрасен этот мир": "Bu dunyo qanday go‘zal",
"Объяснять, как с помощью музыкальных произведений можно показать красоту окружающего мира и призвать беречь его.": "Musiqiy asarlar yordamida atrofdagi dunyoning go‘zalligini qanday ko‘rsatish va uni asrashga chaqirish mumkinligini tushuntirish.",
"Берегём мир": "Dunyoni asraymiz",
"Если все люди на планете будут беречь и охранять окружающую среду, то мир вокруг нас будет ярким и многообразным.": "Agar sayyoradagi barcha odamlar atrof-muhitni asrasa va muhofaza qilsa, atrofimizdagi dunyo yorqin va rang-barang bo‘ladi.",
"Путешествие": "Sayohat",
"Слово «путешествие» по-казахски «саяхат», а по-английски «voyage». Музыка тоже может отправить нас в путешествие по красивым местам.": "«Sayohat» so‘zi qozoqchada «sayahat», inglizchada «voyage». Musiqa ham bizni go‘zal joylarga sayohatga olib chiqishi mumkin.",
"Песня Д. Тухманова": "D. Tuxmanov qo‘shig‘i",
"Песня «Как прекрасен этот мир» написана композитором Д. Тухмановым. В ней важно услышать, как солирующий голос и подголоски дополняют друг друга.": "«Bu dunyo qanday go‘zal» qo‘shig‘ini bastakor D. Tuxmanov yozgan. Unda yakkaxon ovoz va jo‘rovozlar bir-birini qanday to‘ldirishini eshitish muhim.",
"Поющий бархан": "Kuylovchi barxan",
"«Поющий бархан» — природная достопримечательность Казахстана. Он находится в 180 км от города Алматы, на территории Государственного Национального природного парка «Алтынемель».": "«Kuylovchi barxan» — Qozog‘istonning tabiiy diqqatga sazovor joyi. U Almati shahridan 180 km uzoqlikda, «Oltinemel» davlat milliy tabiat bog‘i hududida joylashgan.",
"Экологический туризм": "Ekologik turizm",
"Термин «экологический туризм» в 1983 году ввёл мексиканский экономист-эколог Гектор Цебаллос-Ласкурейн. Он призывал туристов не оставлять после отдыха загрязнения и уважать культурные традиции народа.": "«Ekologik turizm» atamasini 1983 yilda meksikalik iqtisodchi-ekolog Hektor Tsebayos-Laskurein kiritgan. U turistlarni dam olgandan keyin ifloslik qoldirmaslikka va xalqning madaniy an’analarini hurmat qilishga chaqirgan.",
"Разложи темы по страницам журнала": "Mavzularni jurnal sahifalariga joylashtir",
"Устный журнал «Как прекрасен этот мир» состоит из страниц, и у каждой своя тема. Определи, к какой странице относится сообщение.": "«Bu dunyo qanday go‘zal» og‘zaki jurnali sahifalardan iborat, har birining o‘z mavzusi bor. Xabar qaysi sahifaga tegishli ekanini aniqla.",
"К какой странице журнала относится сообщение?": "Xabar jurnalning qaysi sahifasiga tegishli?",
