"Композиторлар шабыттан, қиялдан, туған жеріне, халқына және табиғатына деген сүйіспеншіліктен шығарма жазады. Біз сүйіспеншілігімізді сөзбен айтсақ, олар музыкамен баяндайды.": "Bastakorlar ilhomdan, xayoldan, tug‘ilgan yerga, xalqqa va tabiatga bo‘lgan muhabbatdan asar yozadilar. Biz muhabbatimizni so‘z bilan aytsak, ular musiqa bilan hikoya qiladilar.",
"Модест Петрович Мусоргский (1839–1881) — орыстың ұлы композиторы. Ол «Хованщина» операсына жазған «Мәскеу өзеніндегі таң» кіріспесімен танымал: онда арайлап атқан таң бейнеленеді.": "Modest Petrovich Musorgskiy (1839–1881) — rus xalqining buyuk bastakori. U «Xovanshchina» operasiga yozgan «Moskva daryosidagi tong» kirish qismi bilan mashhur: unda yorishib kelayotgan tong tasvirlangan.",
"Эдвард Григ (1843–1907) — Норвегияның әйгілі композиторы, пианист, дирижёр. Ол «Пер Гюнт» сюитасының «Таң» шығармасында туған жерінің табиғатын, таң шапағын көркемдеуіш құралдар арқылы суреттеген.": "Edvard Grig (1843–1907) — Norvegiyaning mashhur bastakori, pianinochi, dirijyor. U «Per Gint» syuitasining «Tong» asarida tug‘ilgan yurtining tabiatini, tong shu’lasini badiiy vositalar orqali tasvirlagan.",
"С. Еркімбеков": "S. Erkimbekov",
"Серік Еркімбеков — белгілі композитор, ҚР еңбек сіңірген қайраткері. Оның «Отан таңы» шығармасы туған жердің сұлулығын көрсетеді.": "Serik Yerkimbekov — taniqli bastakor, Qozog‘iston Respublikasining xizmat ko‘rsatgan arbobi. Uning «Vatan tongi» asari tug‘ilgan yurtning go‘zalligini ko‘rsatadi.",
"Жаңа сөздер": "Yangi so‘zlar",
"Опера — вокалдық және аспаптық музыканы, театр өнерін біріктіретін жанр. Сюита — бір идеяға бағындырылған әртүрлі пьесалардан құралған шығарма. Интерпретация — орындаушының шығарманы көркем түсіндіруі.": "Opera — vokal va cholg‘u musiqasini, teatr san’atini birlashtiruvchi janr. Syuita — bir g‘oyaga bo‘ysundirilgan turli pyesalardan tuzilgan asar. Interpretatsiya — ijrochining asarni badiiy izohlashi.",
"Композиторды тап": "Bastakorni toping",
"Әр карточканы қай композиторға қатысты екенін анықта.": "Har bir kartochka qaysi bastakorga tegishli ekanini aniqlang.",
"Бұл қай композиторға қатысты?": "Bu qaysi bastakorga tegishli?",
