"Айту: А.Н. Скрябиннің «Прометей» симфониялық поэмасы мен «Жалын биі», «Жел» шығармаларында от пен жел қалай бейнеленетінін түсіндіру.": "Aytib berish: A.N. Skryabinning «Prometey» simfonik poemasi hamda «Alanga raqsi», «Shamol» asarlarida olov va shamol qanday tasvirlanishini tushuntirish.",
"От — өмір символы": "Olov — hayot ramzi",
"Адам отсыз өмір сүре алмайды. От ежелден өмірдің және жылулықтың символы болып саналады.": "Inson olovsiz yashay olmaydi. Olov qadimdan hayot va issiqlik ramzi hisoblanadi.",
"«Прометей» поэмасы": "«Prometey» poemasi",
"Бұл — А.Н. Скрябиннің симфониялық поэмасы. Оның екінші аты — «Поэма огня», яғни «От туралы поэма». Ол 1910 жылы жазылған.": "Bu — A.N. Skryabinning simfonik poemasi. Uning ikkinchi nomi — «Poema ognya», ya’ni «Olov haqida poema». U 1910-yilda yozilgan.",
"Прометей туралы аңыз": "Prometey haqidagi rivoyat",
"Поэма ежелгі грек аңызына негізделген. Прометей Олимптен отты рұқсатсыз алып кетіп, адамдарға сыйлаған. Сол үшін құдайлар оны жартасқа мәңгі байлап қойған.": "Poema qadimgi yunon rivoyatiga asoslangan. Prometey Olimpdan olovni ruxsatsiz olib ketib, odamlarga hadya qilgan. Shu uchun xudolar uni qoyaga abadiy bog‘lab qo‘yishgan.",
"Жарық партиясы": "Yorug‘lik partiyasi",
"Скрябин оркестрге хор мен «жарық партиясын» қосқан. Композитордың ойынша, музыкамен бірге түрлі түсті прожектор сәулелері ауысып тұруы керек.": "Skryabin orkestrga xor va «yorug‘lik partiyasi»ni qo‘shgan. Bastakorning fikricha, musiqa bilan birga rang-barang projektor nurlari almashib turishi kerak.",
"Симфониялық поэма": "Simfonik poema",
"Симфониялық поэма — бір бөлімді симфониялық музыка жанры. Бұл — оркестрге арналған бағдарламалық шығарма.": "Simfonik poema — bir bo‘limli simfonik musiqa janri. Bu — orkestr uchun dasturli asar.",
"Шығарманы тап": "Asarni toping",
"Әр белгіні сәйкес шығармаға қой.": "Har bir belgini mos asarga qo‘ying.",
"Бұл қай шығармаға жатады?": "Bu qaysi asarga tegishli?",
"«Жалын биі»": "«Alanga raqsi»",
