"19-сабақ. Музыкадағы табиғат құбылыстары (жалғасы)": "Dars 19. Musiqada tabiat hodisalari (davomi)",
"Музыкадағы табиғат құбылыстары (жалғасы)": "Musiqada tabiat hodisalari (davomi)",
"Музыка арқылы су мен желдің бейнесін елестетіп, шығармаларды суреттермен және билермен салыстыра білу.": "Musiqa orqali suv va shamol tasvirini tasavvur qilib, asarlarni rasmlar va raqslar bilan solishtira bilish.",
"Су мен жел – табиғат құбылыстары": "Suv va shamol – tabiat hodisalari",
"«Сусыз өмір жоқ», «Жел ауа тазартады» дейді. Әр табиғат құбылысының адам өмірінде өз орны бар.": "«Suvsiz hayot yo‘q», «Shamol havoni tozalaydi» deyishadi. Har bir tabiat hodisasining inson hayotida o‘z o‘rni bor.",
"«Ақ бұлақ әуені»": "«Oq buloq ohangi»",
"Бұл шығарманың музыкасын С. Еркімбеков жазған. Тыңдағанда көз алдыңа судың көріністері елестейді.": "Bu asarning musiqasini S. Yerkimbekov yozgan. Tinglaganda ko‘z oldingizda suv manzaralari gavdalanadi.",
"«Жел әуені»": "«Shamol ohangi»",
"Бұл шығарманың да музыкасын С. Еркімбеков жазған. Композитор музыка арқылы желдің уілін бейнелеген.": "Bu asarning ham musiqasini S. Yerkimbekov yozgan. Bastakor musiqa orqali shamolning uvillashini tasvirlagan.",
"Музыка мен суретті салыстыру": "Musiqa bilan rasmni solishtirish",
"«Ақ бұлақ әуенін» Ө. Қастеевтің «Өмір-өзен» картинасымен, «Жел әуенін» И.В. Ломанованың «Күзгі жел» картинасымен салыстырамыз. Айырмашылығы мен ұқсастығын табамыз.": "«Oq buloq ohangi»ni O. Qasteyevning «Hayot-daryo» kartinasi bilan, «Shamol ohangi»ni I.V. Lomanovaning «Kuzgi shamol» kartinasi bilan solishtiramiz. Farqi va o‘xshashligini topamiz.",
"«Жел» әнінің өлеңін Н. Әлімқұлов, әнін М. Маңғытаев жазған. Оны мәнерлеп орындауға тырысамыз.": "«Shamol» qo‘shig‘ining she’rini N. Alimqulov, musiqasini M. Mang‘ittayev yozgan. Uni ifodali ijro etishga harakat qilamiz.",
"Су және жел тақырыбы": "Suv va shamol mavzusi",
"Әр карточканы дұрыс топқа орналастыр: су тақырыбына жата ма, әлде жел тақырыбына ма?": "Har bir kartochkani to‘g‘ri guruhga joylang: suv mavzusiga kiradimi yoki shamol mavzusigami?",
"Қай тақырыпқа жатады?": "Qaysi mavzuga kiradi?",
