"20-сабақ. Музыкадағы жыл мезгілдері": "Dars 20. Musiqada yil fasllari",
"Музыкадағы жыл мезгілдері": "Musiqada yil fasllari",
"Жыл мезгілдеріне арналған А. Вивальди концерттерін және оркестр туралы негізгі ұғымдарды (оркестр, дирижёр, партитура, концерт) атай білу.": "Yil fasllariga bag‘ishlangan A. Vivaldi konsertlarini va orkestr haqidagi asosiy tushunchalarni (orkestr, dirijyor, partitura, konsert) ayta bilish.",
"Жылдың төрт мезгілі": "Yilning to‘rt fasli",
"Қыс, көктем, жаз, күз бірінен кейін бірі ауысып отырады. Әр мезгілдің өз әсемдігі бар, сондықтан оған арнап өлеңдер, әндер мен музыкалық шығармалар жазылған.": "Qish, bahor, yoz, kuz birin-ketin almashib turadi. Har bir fasning o‘z go‘zalligi bor, shuning uchun unga atab she’rlar, qo‘shiqlar va musiqiy asarlar yozilgan.",
"Вивальди (1678–1741) – итальян композиторы, асқан шебер скрипкашы, дирижёр. Ол Венеция қаласында дүниеге келген.": "Vivaldi (1678–1741) – italiyalik bastakor, mohir skripkachi, dirijyor. U Venetsiya shahrida tug‘ilgan.",
"«Жыл мезгілдері» концерттері": "«Yil fasllari» konsertlari",
"Вивальдидің ең танымал шығармасы – «Жыл мезгілдері» деп аталатын скрипкаға арналған төрт концерт. Олар: «Көктем», «Жаз», «Күз», «Қыс».": "Vivaldining eng mashhur asari – «Yil fasllari» deb ataladigan skripka uchun to‘rt konsert. Ular: «Bahor», «Yoz», «Kuz», «Qish».",
"«Шат көңіл» әні": "«Shod kayfiyat» qo‘shig‘i",
