"Табыңыз: Жұрт алдында орындалу": "Toping: Omma oldida ijro etilishi",
"Табыңыз: Аспапқа арналған шығарма": "Toping: Cholg‘uga mo‘ljallangan asar",
"21-сабақ. Музыкадағы жыл мезгілдері (жалғасы)": "Dars 21. Musiqada yil fasllari (davomi)",
"Музыкадағы жыл мезгілдері (жалғасы)": "Musiqada yil fasllari (davomi)",
"Жыл мезгілдері туралы шығармаларды таныру, канон, оркестр, дирижёр, симфониялық поэма және сюита ұғымдарын түсіндіру.": "Yil fasllari haqidagi asarlarni tanish; kanon, orkestr, dirijyor, simfonik poema va syuita tushunchalarini tushuntirish.",
"Жыл – он екі ай": "Yil – o‘n ikki oy",
"Жыл мезгілдеріне арналған ән мен музыкалық шығарма көп. Домбырашы, композитор Төлепберген Тоқжанов домбыраға арнап «Жыл – он екі ай» пьесаларын жазған, онда он екі айдың ерекшелігі суреттелген.": "Yil fasllariga bag‘ishlangan qo‘shiq va musiqiy asarlar ko‘p. Dombirachi, bastakor Tolepbergen Toqjanov dombiraga atab «Jyl – on eki ay» pyesalarini yozgan, unda o‘n ikki oyning o‘ziga xosligi tasvirlangan.",
"«Жұмбақ әуендер» ойыны": "«Jumbaq auender» o‘yini",
"Тыңдалған музыкаға қарай шығарма атын түсі сәйкес келетін қағазбен көрсетесің: «Ақпан – Бұрқасын» – ақ, «Қыркүйек – Күзгі той» – сары, «Сәуір – Көктемгі тамшылар» – жасыл, «Шілде – Жаз биі» – қызыл. Түстерді дұрыс көрсеткен топ жеңімпаз болады.": "Tinglagan musiqangga qarab asar nomini rangi mos keladigan qog‘oz bilan ko‘rsatasan: «Aqpan – Burqasyn» – oq, «Qyrkuyek – Kuzgi toy» – sariq, «Sauir – Koktemgi tamshylar» – yashil, «Shilde – Jaz biyi» – qizil. Ranglarni to‘g‘ri ko‘rsatgan guruh g‘olib bo‘ladi.",
"Канон": "Kanon",
"Әнді орындаудың бір тәсілі – канон. Әнді топтарға бөліп, шумақты кезектесіп, бірінен кейін бірі бастап айтады. «Жау-жау, жаңбыр!» әнінің сөзін Ш. Сариев, әнін К. Дүйсекеев жазған.": "Qo‘shiqni ijro etishning bir usuli – kanon. Qo‘shiq guruhlarga bo‘linadi va bandni navbatma-navbat, birin-ketin boshlab aytadi. «Jau-jau, janbyr!» qo‘shig‘ining so‘zini Sh. Sariev, musiqasini K. Duysekeev yozgan.",
"Оркестр – түрлі музыкалық аспаптарда шығармалар орындайтын ұжым. Дирижёр – музыкант-орындаушылар ұжымын басқаратын маман.": "Orkestr – turli musiqa asboblarida asarlar ijro etadigan jamoa. Dirijyor – musiqachi-ijrochilar jamoasini boshqaradigan mutaxassis.",
"Симфониялық поэма және сюита": "Simfonik poema va syuita",
"Симфониялық поэма – бір бөлімді, симфониялық оркестрге арналған бағдарламалық шығарма. Сюита – бір идеяға бағындырылған, әртүрлі пьесадан құрастырылған музыкалық шығарма.": "Simfonik poema – bir qismli, simfonik orkestr uchun yozilgan dasturli asar. Syuita – bitta g‘oyaga bo‘ysundirilgan, turli pyesalardan tuzilgan musiqiy asar.",
"Аспап па, әлде ұжым не маман ба?": "Asbobmi, jamoami yoki mutaxassismi?",
