"22-сабақ. Арал тағдыры — ел тағдыры": "Dars 22. Orol taqdiri – el taqdiri",
"Арал тағдыры — ел тағдыры": "Orol taqdiri – el taqdiri",
"Арал мәселесі туралы музыка мен суреттің көмегімен айта білу және Қ. Сайжанның күйін, Т. Шевченконың пейзаждарын, «Аралым» әнін ажырату.": "Orol muammosi haqida musiqa va rasm yordamida gapira olish hamda Q. Sayjanning kuyini, T. Shevchenkoning peyzajlarini, «Aralym» qo‘shig‘ini ajrata olish.",
"Арал мәселесі": "Orol muammosi",
"Арал теңізі тартылып барады. Желмен ұшқан ащы тұз табиғатқа да, адам денсаулығына да зиян келтіреді.": "Orol dengizi qurib bormoqda. Shamolda uchgan achchiq tuz tabiatga ham, inson salomatligiga ham zarar yetkazadi.",
"Бүкіл әлемнің қайғысы": "Butun dunyoning qayg‘usi",
"Арал мәселесі тек Қазақстан үшін ғана емес, басқа мемлекеттер үшін де өзекті. Отандық және шетелдік ғалымдар Аралды қайта толтыру жолдарын қарастыруда.": "Orol muammosi faqat Qozog‘iston uchun emas, boshqa davlatlar uchun ham dolzarb. Mahalliy va xorijiy olimlar Orolni qayta to‘ldirish yo‘llarini ko‘rib chiqmoqda.",
"«Арал тағдыры» күйі": "«Aral tagdyry» kuyi",
"Бұл — Қ. Сайжанның күйі. Күйдің орындалуы адамның мұңды, қайғылы сезімдерін білдіреді, композитор тыңдаушыға маңызды ойды жеткізуге тырысқан.": "Bu – Q. Sayjanning kuyi. Kuyning ijrosi insonning mungli, g‘amgin tuyg‘ularini ifodalaydi, bastakor tinglovchiga muhim fikrni yetkazishga harakat qilgan.",
"Тарас Шевченко": "Taras Shevchenko",
"Тарас Григорьевич Шевченко (1814–1861) — украиннің әйгілі ақыны әрі суретшісі. 1838 жылы Санкт-Петербург қаласының Көркемсурет академиясын бітірген.": "Taras Grigorevich Shevchenko (1814–1861) – ukrainalik mashhur shoir va rassom. 1838-yilda Sankt-Peterburg shahridagi Badiiy akademiyani tamomlagan.",
"Шевченко және Арал": "Shevchenko va Orol",
"1848 жылы ол А.И. Бутаковтың басшылығымен Арал теңізін зерттеу экспедициясына қатысып, 350-ден астам пейзаж, портрет салған. Маңғыстау облысындағы Түпқараған ауданының орталығы «Форт-Шевченко» деп аталады.": "1848-yilda u A.I. Butakov boshchiligida Orol dengizini o‘rganish ekspeditsiyasida qatnashib, 350 dan ortiq peyzaj va portret chizgan. Mang‘istov viloyatidagi Tupqaragan tumanining markazi «Fort-Shevchenko» deb ataladi.",
"Кім туралы немесе кімнің шығармасы?": "Kim haqida yoki kimning asari?",
"Бұл карточка қай топқа жатады?": "Bu kartochka qaysi guruhga kiradi?",
"Арал туралы музыка авторлары": "Orol haqidagi musiqa mualliflari",
"Украиннің әйгілі ақыны әрі суретшісі": "Ukrainalik mashhur shoir va rassom",
"Ол екі өнерді қатар меңгерген.": "U ikki san’atni birdek egallagan.",
"1848 жылы Арал теңізін зерттеу экспедициясына қатысқан": "1848-yilda Orol dengizini o‘rganish ekspeditsiyasida qatnashgan",
"Экспедицияны А.И. Бутаков басқарған.": "Ekspeditsiyani A.I. Butakov boshqargan.",
"350-ден астам пейзаж, портрет салған": "350 dan ortiq peyzaj va portret chizgan",
