"23-сабақ. Ядролық жарылысқа — «Жоқ» дейміз!": "Dars 23. Yadro portlashiga – «Yo‘q» deymiz!",
"Ядролық жарылысқа — «Жоқ» дейміз!": "Yadro portlashiga – «Yo‘q» deymiz!",
"Полигон мен радиация ұғымдарын түсіндіру, «Заман-ай» мен «Ядролық жарылысқа — «Жоқ» дейміз!» әндерінің авторларын атау және әндердің мазмұнын сипаттау.": "Poligon va radiatsiya tushunchalarini tushuntirish, «Zaman-ay» va «Yadro portlashiga – “Yo‘q” deymiz!» qo‘shiqlarining mualliflarini aytish va qo‘shiqlarning mazmunini tasvirlash.",
"Ядролық қарусыз аймақ": "Yadro qurolsiz hudud",
"Қазақстан өзін «ядролық қарусыз аймақ» деп жариялады. Біздің елдің мақсаты — бейбітшілік пен адамдардың денсаулығын сақтау.": "Qozog‘iston o‘zini «yadro qurolsiz hudud» deb e’lon qildi. Yurtimizning maqsadi – tinchlik va odamlar salomatligini saqlash.",
"Декларация": "Deklaratsiya",
"1991 жылы 28 тамызда Декларация қабылданды. Семей полигоны жабылды, ел атом қаруынан бас тарту жолын жалғастырды.": "1991-yil 28-avgustda Deklaratsiya qabul qilindi. Semey poligoni yopildi, mamlakat atom qurolidan voz kechish yo‘lini davom ettirdi.",
"Полигон": "Poligon",
"Полигон — қару-жарақ пен әскери техникаға, көбінесе ядролық сынақ жүргізуге арналған арнайы бөлінген және жабдықталған аймақ.": "Poligon – qurol-yarog‘ va harbiy texnikani, ko‘pincha yadro qurolini sinash uchun maxsus ajratilgan va jihozlangan hudud.",
"Радиация": "Radiatsiya",
"Радиация (өткір радиация) — ядролық жарылыс кезінде тарайтын радиоактивті сәулелер.": "Radiatsiya (o‘tkir radiatsiya) – yadro portlashi paytida tarqaladigan radioaktiv nurlar.",
"Екі ән": "Ikki qo‘shiq",
"«Заман-ай» әнінің өлеңін Ү. Есдәулет, әнін Т. Мұхамеджанов жазған. «Ядролық жарылысқа — «Жоқ» дейміз!» әнінің өлеңін Р. Наурызбаева, әнін Н. Мирманов жазған.": "«Zaman-ay» qo‘shig‘ining she’rini U. Esdaulet, musiqasini T. Muhamedjanov yozgan. «Yadro portlashiga – “Yo‘q” deymiz!» qo‘shig‘ining she’rini R. Nauryzbaeva, musiqasini N. Mirmanov yozgan.",
"Әндер мен авторларды ретте": "Qo‘shiqlar va mualliflarni joylashtir",
"Әр карточканы дұрыс әнге қой.": "Har bir kartochkani to‘g‘ri qo‘shiqqa qo‘y.",
"Бұл қай әнге қатысты?": "Bu qaysi qo‘shiqqa tegishli?",
"Заман-ай": "Zaman-ay",
"Ү. Есдәулет — өлеңін жазған": "U. Esdaulet – she’rini yozgan",
"Бұл ән бейнетаспадан тыңдалады.": "Bu qo‘shiq videotasmadan tinglanadi.",
