"Ғазиза Жұбанова": "G‘aziza Jubanova",
"Ғазиза Жұбанова (1927–1993) — композитор. Ол Алматы қаласында музыканттар отбасында дүниеге келген. Әкесі — атақты композитор Ахмет Жұбанов.": "G‘aziza Jubanova (1927–1993) – bastakor. U Almati shahrida musiqachilar oilasida tug‘ilgan. Otasi – mashhur bastakor Ahmet Jubanov.",
"Композитордың шығармалары": "Bastakorning asarlari",
"Ғ. Жұбанова опера, балет, оратория, ән, хор жазған. Оның «Хиросима» балеті Қазақстан музыка өнерінде үлкен жаңалық болды.": "G‘. Jubanova opera, balet, oratoriya, qo‘shiq, xor asarlari yozgan. Uning «Xirosima» baleti Qozog‘iston musiqa san’atida katta yangilik bo‘ldi.",
"Мемлекеттік сыйлық": "Davlat mukofoti",
"«Хиросима» балеті үшін Ғ. Жұбановаға 1970 жылы Қазақстанның Мемлекеттік сыйлығы берілді.": "«Xirosima» baleti uchun G‘. Jubanovaga 1970-yilda Qozog‘iston Davlat mukofoti berildi.",
"Балет": "Balet",
"Балет — музыкалық-хореографиялық қойылым. Оның мазмұны, кейіпкерлердің ой-сезімі музыка мен би арқылы көрсетіледі.": "Balet – musiqiy-xoreografik sahna asari. Uning mazmuni, qahramonlarning fikr va tuyg‘ulari musiqa va raqs orqali ko‘rsatiladi.",
"Реквием": "Rekviem",
"Реквием — көпдауысты, қайғылы музыкалық шығарма. «Хиросима» балетінің соңында реквием-гимн естіледі: музыка жер бетінде ешқашан ядролық жарылыстар болмасын деген тілекті жеткізеді.": "Rekviem – ko‘p ovozli, g‘amgin musiqiy asar. «Xirosima» baletining oxirida rekviem-madhiya yangraydi: musiqa yer yuzida hech qachon yadro portlashlari bo‘lmasin degan tilakni yetkazadi.",
"Кім? Не?": "Kim? Nima?",
"Әр карточканы дұрыс топқа орналастыр: композитор, сөзін жазған не аударған адам немесе шығарма атауы.": "Har bir kartochkani to‘g‘ri guruhga joylashtir: bastakor, so‘zini yozgan yoki tarjima qilgan odam yoki asar nomi.",
