"Атап айту: «Сарбаздар жыры» мен «Мәңгілік алау» балетінің авторларын, тақырыбын және ел қорғау туралы музыканың мәнін түсіндіру.": "Ayting: «Sarbozlar qo‘shig‘i» va «Mangu alanga» baleti mualliflarini, mavzusini va Vatanni himoya qilish haqidagi musiqaning ma’nosini tushuntiring.",
"Ата-бабалар аманаты": "Ota-bobolar vasiyati",
"Кім болсақ та, қайда жүрсек те, өз туған жерімізді, табиғатымызды аялап, қорғауымыз керек. Бұл — ата-бабаларымыздың бізге қалдырған аманаты.": "Kim bo‘lsak ham, qayerda yursak ham, o‘z tug‘ilgan yurtimizni, tabiatimizni asrab-avaylashimiz va himoya qilishimiz kerak. Bu — ota-bobolarimizning bizga qoldirgan vasiyatidir.",
"Табиғатты қорғау": "Tabiatni himoya qilish",
"Арал теңізі мен Семей полигоны мәселелерін өткен сабақтарда білдік. Жеріміздің табиғатына зиян келіп жатыр, сондықтан елімізді, қоршаған ортаны қорғауға дайын болуымыз керек.": "Orol dengizi va Semipalatinsk poligoni muammolarini o‘tgan darslarda bildik. Yurtimiz tabiatiga zarar yetmoqda, shuning uchun biz yurtimizni va atrof-muhitni himoya qilishga tayyor bo‘lishimiz kerak.",
"«Сарбаздар жыры»": "«Sarbozlar qo‘shig‘i»",
"Бұл — қазақ сарбаздары туралы ән. Өлеңін А. Асылбек жазған, әнін Н. Айтбаева шығарған. Әнде қайырма бар.": "Bu — qozoq sarbozlari haqidagi qo‘shiq. She’rini A. Asilbek yozgan, kuyini N. Aytbayeva bastalagan. Qo‘shiqda naqorat bor.",
"Әннің тақырыбы": "Qo‘shiqning mavzusi",
"«Сарбаздар жыры» елін қорғайтын батыл сарбаздарды дәріптейді. Ән тыныштық пен бейбіт өмір арманын жеткізеді.": "«Sarbozlar qo‘shig‘i» yurtini himoya qiladigan jasur sarbozlarni ulug‘laydi. Qo‘shiq tinchlik va osoyishta hayot orzusini yetkazadi.",
"«Мәңгілік алау» балеті": "«Mangu alanga» baleti",
"Бұл — бір актілі балеттен үзінді, музыкасын С. Еркімбеков жазған. Балет 12 нөмірден тұрады және соғыс пен бейбітшілік туралы айтады. Ондағы нөмірлердің бірі — «Реквием».": "Bu — bir pardali baletdan parcha, musiqasini S. Yerkimbekov yozgan. Balet 12 raqamdan iborat va urush hamda tinchlik haqida hikoya qiladi. Undagi raqamlardan biri — «Rekviyem».",
"Қай шығармаға қатысты?": "Qaysi asarga tegishli?",
"Әр карточканы дұрыс шығарманың тобына жатқыз.": "Har bir kartochkani to‘g‘ri asar guruhiga joylashtiring.",
"Бұл қай шығармаға қатысты?": "Bu qaysi asarga tegishli?",
