"26-сабақ. Қоршаған ортамызды сақтайық!": "26-dars. Atrof-muhitimizni asraylik!",
"Қоршаған ортамызды сақтайық!": "Atrof-muhitimizni asraylik!",
"Қоршаған ортаны қорғайтын мамандықтарды атау, «Атамекен» әні мен «Мәңгілік алау» балетін таныту және кейіпкер, көрініс ұғымдарын түсіндіру.": "Atrof-muhitni himoya qiladigan kasblarni ayting, «Atameken» qo‘shig‘i va «Mangu alanga» baletini tanishtiring hamda qahramon, ko‘rinish tushunchalarini tushuntiring.",
"«Атамекен» әні": "«Atameken» qo‘shig‘i",
"Бұл әннің сөзін Ш. Сариев, әнін Ж. Тұяқбаев жазған. Ән Отанымыздың әдемі табиғатын мадақтайды.": "Bu qo‘shiqning so‘zini Sh. Sariyev, kuyini J. Tuyakbayev yozgan. Qo‘shiq Vatanimizning go‘zal tabiatini madh etadi.",
"Төрт топ, төрт мамандық": "To‘rt guruh, to‘rtta kasb",
"Сабақта оқушылар төрт топқа бөлінеді: Экологтер, Өртсөндірушілер, Балықшылар және Орманшылар. Әр топ өз мамандығы туралы таныстырылым дайындайды.": "Darsda o‘quvchilar to‘rt guruhga bo‘linadi: ekologlar, o‘t o‘chiruvchilar, baliqchilar va o‘rmonchilar. Har bir guruh o‘z kasbi haqida taqdimot tayyorlaydi.",
"Экологтер мен өртсөндірушілер": "Ekologlar va o‘t o‘chiruvchilar",
"Эколог қоршаған ортамен үйлесімді өмір сүруге көмектеседі. Өртсөндірушілер күні-түні қауіп пен қатерден сақтап, өрт шықса көмекке келеді.": "Ekolog atrof-muhit bilan uyg‘un yashashga yordam beradi. O‘t o‘chiruvchilar kecha-kunduz xavf-xatardan asraydi, yong‘in chiqsa yordamga keladi.",
"Балықшылар мен орманшылар": "Baliqchilar va o‘rmonchilar",
"Балықшылар балықтың қасиетін біледі және балық өсетін су ортасының тазалығын сақтайды. Орманшылар орманды қорғап, түрлі міндеттерді атқарады.": "Baliqchilar baliqning xususiyatlarini biladi va baliq o‘sadigan suv muhitining tozaligini saqlaydi. O‘rmonchilar o‘rmonni himoya qilib, turli vazifalarni bajaradi.",
"Бұл балеттің музыкасын С. Еркімбеков жазған. Балет — музыкалық-хореографиялық қойылым. Онда кейіпкерлер сөйлемей, би мен музыка арқылы өз ойын көрсетеді.": "Bu balet musiqasini S. Yerkimbekov yozgan. Balet — musiqiy-xoreografik sahna asari. Unda qahramonlar gapirmaydi, raqs va musiqa orqali o‘z fikrini ko‘rsatadi.",
"Кім не істейді?": "Kim nima qiladi?",
"Әр сөйлемді қай мамандыққа жататынын тап.": "Har bir gap qaysi kasbga tegishli ekanini toping.",
"Бұл қай мамандыққа қатысты?": "Bu qaysi kasbga tegishli?",
